package referenz;

import java.util.*;

public class Solution {
    private static class LongHolder {
        long value = Long.MAX_VALUE;
    }

    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        boolean[] used = new boolean[n];
        int[] perm = new int[n];
        LongHolder bestHolder = new LongHolder();
        dfs(0, n, nums1, nums2, used, perm, bestHolder);
        return bestHolder.value == Long.MAX_VALUE ? -1 : bestHolder.value;
    }

    private void dfs(int pos, int n, int[] nums1, int[] nums2,
                     boolean[] used, int[] perm, LongHolder bestHolder) {
        if (pos == n) {
            long cost = computeCost(perm, n);
            bestHolder.value = Math.min(bestHolder.value, cost);
            return;
        }
        for (int idx = 0; idx < n; idx++) {
            if (!used[idx] && nums1[idx] != nums2[pos]) {
                used[idx] = true;
                perm[pos] = idx;
                dfs(pos + 1, n, nums1, nums2, used, perm, bestHolder);
                used[idx] = false;
            }
        }
    }

    private long computeCost(int[] perm, int n) {
        boolean[] visited = new boolean[n];
        long cost = 0;
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int j = i;
                int len = 0;
                long sum = 0;
                int minIdx = Integer.MAX_VALUE;
                while (!visited[j]) {
                    visited[j] = true;
                    len++;
                    sum += j;
                    if (j < minIdx) minIdx = j;
                    j = perm[j];
                }
                if (len <= 1) continue;
                if (len == 2) {
                    cost += sum;
                } else {
                    cost += sum + (len - 2) * (long)minIdx;
                }
            }
        }
        return cost;
    }
}

