public class Solution {
    /**
     * Returns the minimum number of operations required to transform the given
     * integer {@code n} into 0 using the specified bit‑flipping rules.
     *
     * The optimal solution for the standard problem is:
     *   answer = number_of_1_bits + number_of_contiguous_runs_of_1_bits - 1
     *
     * @param n a non‑negative integer
     * @return the minimum number of operations to reduce {@code n} to 0
     */
    public int minimumOneBitOperations(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }
        if (n == 0) {
            return 0;
        }

        int cnt1 = 0;   // number of 1 bits
        int runs = 0;   // number of contiguous runs of 1 bits
        boolean prevOne = false;

        for (int i = 0; i < 32; i++) {
            if ((n & 1) == 1) {
                cnt1++;
                if (!prevOne) {
                    runs++;   // start of a new run
                }
                prevOne = true;
            } else {
                prevOne = false;
            }
            n >>>= 1; // shift right
        }

        int result = cnt1 + runs - 1;
        // The result is always non‑negative for n > 0
        assert result >= 0 : "Result should never be negative";
        return result;
    }
}

