import java.util.*;

public class Solution {
    private static final long MOD = 1_000_000_007L;

    public int numberOfUniqueGoodSubsequences(String binary) {
        if (binary == null || binary.isEmpty()) {
            return 0;
        }

        int firstOne = binary.indexOf('1');
        long g1 = 0; // number of distinct subsequences that start with '1'

        if (firstOne != -1) {
            String suffix = binary.substring(firstOne + 1);
            int n = suffix.length();
            long[] dp = new long[n + 1];
            dp[0] = 1; // empty subsequence
            int[] last = new int[2];
            Arrays.fill(last, -1);

            for (int i = 1; i <= n; i++) {
                char c = suffix.charAt(i - 1);
                int idx = c - '0';
                long val = (dp[i - 1] * 2) % MOD;
                if (last[idx] != -1) {
                    val = (val - dp[last[idx]] + MOD) % MOD;
                }
                dp[i] = val;
                last[idx] = i - 1;
            }
            g1 = dp[n] % MOD;
        }

        long ans = g1;
        if (binary.indexOf('0') != -1) {
            ans = (ans + 1) % MOD; // add the subsequence "0"
        }
        return (int) ans;
    }
}

