import java.util.*;

public class Solution {
    public List<Integer> findNumOfValidWords(String[] words, String[] puzzles) {
        Map<String, Integer> wordCount = new HashMap<>();

        // Count occurrences of each bit pattern in words
        for (String word : words) {
            int mask = 0;
            for (char c : word.toCharArray()) {
                mask |= 1 << (c - 'a');
            }
            String binaryMask = Integer.toBinaryString(mask);
            wordCount.put(binaryMask, wordCount.getOrDefault(binaryMask, 0) + 1);
        }

        List<Integer> result = new ArrayList<>();

        // For each puzzle, count the number of valid words
        for (String puzzle : puzzles) {
            int mask = 0;
            for (char c : puzzle.toCharArray()) {
                if (c == 'a') continue; 
                mask |= 1 << (c - 'a');
            }

            int count = 0;
            for (Map.Entry<String, Integer> entry : wordCount.entrySet()) {
                String bitPattern = entry.getKey();

                // Remove leading zeros from the bit pattern
                while (bitPattern.startsWith("0")) {
                    bitPattern = bitPattern.substring(1);
                }

                if (!bitPattern.isEmpty() && bitPattern.matches("[01]+")) { 
                    int patternMask = Integer.parseInt(bitPattern);

                    if ((patternMask & mask) == patternMask) { 
                        count += entry.getValue(); 
                    }
                }
            }

            result.add(count);
        }

        return result;
    }
}

